import sys
import math

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
        k = int(next(iterator))
    except StopIteration:
        return

    adj = []
    for _ in range(n):
        row = []
        for _ in range(n):
            row.append(int(next(iterator)))
        adj.append(row)

    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j] == 1:
                edges.append((i, j))

    if not edges:
        print(f"{0.0:.12f}")
        return

    best_val = 0.0

    def compute(stability_values):
        total = 0.0
        for u, v in edges:
            total += stability_values[u] * stability_values[v]
        return total

    max_iter = 10000
    step_factor = 0.99
    current_step = 1.0
    current_vals = [k / n] * n
    current_best = compute(current_vals)

    for _ in range(max_iter):
        improved = False
        new_vals = current_vals[:]

        for i in range(n):
            grad_i = 0.0
            for u, v in edges:
                if u == i:
                    grad_i += current_vals[v]
                elif v == i:
                    grad_i += current_vals[u]

            if grad_i > 0:
                delta = current_step
                if delta > k:
                    delta = k

                test_vals = current_vals[:]
                test_vals[i] += delta

                if test_vals[i] > k:
                    test_vals[i] = k

                test_sum = sum(test_vals)
                if test_sum > k:
                    scale = k / test_sum
                    test_vals = [x * scale for x in test_vals]

                test_val = compute(test_vals)
                if test_val > current_best:
                    current_best = test_val
                    new_vals = test_vals
                    improved = True

        if not improved:
            current_step *= step_factor
            if current_step < 1e-10:
                break
        else:
            current_vals = new_vals

        if current_step < 1e-10:
            break

    print(f"{current_best:.12f}")

if __name__ == "__main__":
    solve()
